// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        int256 price;
        bool ok;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            price = p;
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || price != int256(-1));
    }
}
